import { APP_NAME } from './config.js';
import { renderCalendar, SCHEDULE_COLORS, calendarTime } from './calendar.js';
document.title=APP_NAME;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusText={available:'가능',unavailable:'불가능',avoid:'기피',unknown:'미입력',todo:'시작 전',doing:'진행 중',review:'검토 요청',done:'완료',blocked:'보류',unassigned:'미배정'};
const priorityText={low:'낮음',normal:'보통',high:'높음'};
const week=['일','월','화','수','목','금','토'];
const dateNow=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'});
const addDays=(d,n)=>{const x=new Date(`${d}T12:00:00Z`);x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)};
const min=t=>{const [h,m]=t.split(':').map(Number);return h*60+m};
const hm=n=>`${String(Math.floor(n/60)%24).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
const day=d=>new Date(`${d}T12:00:00Z`).getUTCDay();
