const label=(k)=>statusText[k]||k;
let state={me:null,project:null,tab:'dashboard',schedules:null,tasks:null,meetings:null,notifications:null,prefs:{},selected:[],required:[],selectionInitialized:false,heatDate:dateNow(),mobileDay:dateNow(),recommend:null,createResult:null,modal:null,save:'',scheduleSelectionMode:false,selectedSchedules:{},scheduleDeleting:false,scheduleDeleteRequest:null,collapsed:new Set(),filter:{}};
let toastTimer;
function toast(text){$('#toast').innerHTML=`<div>${esc(text)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').innerHTML='',4500)}
function save(text,error=false){state.save=text;const x=$('#save-status');if(x){x.textContent=text;x.className=`save-status${error?' error':''}`}}
async function api(path,method='GET',body){const opts={method,credentials:'same-origin',headers:{}};if(body!==undefined){opts.headers['content-type']='application/json';opts.body=JSON.stringify(body)}let r;try{r=await fetch('/api'+path,opts)}catch{throw Error('네트워크 연결에 실패했습니다. 다시 시도하세요.')}let data;try{data=await r.json()}catch{throw Error('서버 응답을 읽지 못했습니다. 다시 시도하세요.')}if(!r.ok)throw Object.assign(Error(data.error||'요청에 실패했습니다.'),{status:r.status,data});return data}
async function action(fn){save('저장 중…');try{const x=await fn();save('저장 완료');return x}catch(e){save('저장 실패 · 다시 시도하세요',true);toast(e.message);e.reported=true;throw e}}
const pid=()=>state.me?.project_id;
async function load(){state.me=await api('/me');if(!state.me){render();return}const p=pid();if(state.project&&state.project.id!==p){state.selectionInitialized=false;state.selected=[];state.required=[]}const [project,schedules,tasks,meetings,notifications,prefs]=await Promise.all([api(`/projects/${p}`),api(`/projects/${p}/schedules`),api(`/projects/${p}/tasks`),api(`/projects/${p}/meetings`),api(`/projects/${p}/notifications`),api(`/projects/${p}/preferences`)]);Object.assign(state,{project,schedules,tasks,meetings,notifications,prefs});if(!state.selectionInitialized){state.selected=(prefs.selected?.length?prefs.selected:project.members.filter(x=>x.active).map(x=>x.id)).filter(id=>project.members.some(m=>m.id===id&&m.active));state.required=(prefs.required||[]).filter(id=>state.selected.includes(id));state.selectionInitialized=true}render()}
const member=id=>{const m=state.project?.members.find(x=>x.id===id);return m?(m.nickname+(m.active?'':' (재지정 필요)')):'미배정'};
const mine=()=>state.me?.id;
const activeMembers=()=>state.project.members.filter(x=>x.active);
function nav(){const links=[['dashboard','대시보드'],['mine','내 시간표'],['team','팀 시간표'],['tasks','과제·역할'],['progress','진행 현황'],['settings','설정']];return links.map(([key,title])=>`<button data-tab="${key}" class="${state.tab===key?'active':''}">${title}</button>`).join('')}
function render(){const app=$('#app'),calendarScroll=[...app.querySelectorAll('.calendar-scroll')].map(el=>({top:el.scrollTop,left:el.scrollLeft}));if(!state.me){app.innerHTML=authView();return}app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div><div class="brand">${esc(APP_NAME)}</div><div class="project-name">${esc(state.project?.name||'')}</div></div><nav class="nav">${nav()}</nav><div class="side-foot">${esc(state.me.nickname)} · ${state.me.role==='owner'?'방장':'조원'}<br><button class="link" data-action="logout" style="color:#cbdcfb">로그아웃</button></div></aside><main class="main"><header class="page"><h1>${({dashboard:'대시보드',mine:'내 시간표',team:'팀 시간표와 회의',tasks:'과제와 역할',progress:'진행 현황',settings:'프로젝트 설정'})[state.tab]}</h1><span id="save-status" class="save-status">${esc(state.save)}</span></header>${({dashboard:dashboardView,mine:mineView,team:teamView,tasks:tasksView,progress:progressPage,settings:settingsView})[state.tab]()}</main></div><nav class="bottom-nav">${nav()}</nav>${state.modal?modalView():''}`;app.querySelectorAll('.calendar-scroll').forEach((el,i)=>{if(calendarScroll[i]){el.scrollTop=calendarScroll[i].top;el.scrollLeft=calendarScroll[i].left}})}
function authView(){const invite=new URLSearchParams(location.hash.slice(1)).get('invite')||'';return `<div class="auth"><div class="auth-head"><h1>${esc(APP_NAME)}</h1><p class="muted">팀 프로젝트의 시간과 역할을 한곳에서 맞춰 보세요.</p></div>${state.createResult?`<div class="card success"><h2>접속 정보 보관</h2><p>개인 복구 코드는 새 기기에서 본인 계정을 찾는 데 사용합니다. 남에게 공개하지 마세요. 새로고침 전 안전한 곳에 저장하세요.</p><div class="recovery"><b>복구 코드</b><br><code>${esc(state.createResult.recoveryCode)}</code></div><div class="row" style="margin-top:12px"><button data-copy="${esc(state.createResult.recoveryCode)}">복구 코드 복사</button><button data-action="enter">프로젝트로 이동</button></div>${state.createResult.inviteCode?`<p>초대 코드는 팀원이 참여할 때만 사용합니다.</p><div class="recovery"><b>초대 코드</b><br><code>${esc(state.createResult.inviteCode)}</code></div><div class="row" style="margin-top:12px"><button class="ghost" data-copy="${esc(state.createResult.inviteCode)}">코드 복사</button><button class="ghost" data-copy="${esc(location.origin+'/#invite='+encodeURIComponent(state.createResult.inviteCode))}">초대 링크 복사</button></div>`:''}</div>`:`<div class="auth-grid"><section class="card"><h2>새 프로젝트 만들기</h2><form id="create-form"><label>프로젝트 이름<input name="name" required maxlength="100" placeholder="예: 캡스톤 디자인"></label><label>내 닉네임<input name="nickname" required maxlength="40" placeholder="팀에서 사용할 이름"></label><label>설명 (선택)<textarea name="description" placeholder="프로젝트 목표를 적어 주세요"></textarea></label><label>목표 종료일 (선택)<input type="date" name="goal_date"></label><button>프로젝트 생성</button></form></section><div class="stack"><section class="card"><h2>초대 코드로 참여</h2><form id="join-form"><label>초대 코드<input name="code" required value="${esc(invite)}" autocomplete="off"></label><label>내 닉네임<input name="nickname" required maxlength="40"></label><button>참여하기</button></form></section><section class="card"><h2>기존 계정 복구</h2><p class="muted tiny">닉네임만으로는 계정에 접속할 수 없습니다.</p><form id="recover-form"><label>개인 복구 코드<input name="code" required autocomplete="off"></label><button class="ghost">복구하기</button></form></section></div></div>`}</div>`}
function progressBar(value){return value===null?'<span class="muted">등록된 과제 없음</span>':`<div class="row"><b>${Math.round(value*100)}%</b><div class="progress" style="flex:1"><span style="width:${Math.round(value*100)}%"></span></div></div>`}
function deadlines(){const today=dateNow();return state.tasks.tasks.filter(t=>t.due_date&&t.status!=='done'&&!state.tasks.tasks.some(x=>x.parent_id===t.id)).map(t=>({...t,days:Math.round((new Date(`${t.due_date}T12:00Z`)-new Date(`${today}T12:00Z`))/86400000)}))}
function dashboardView(){const roles=state.tasks.roles.filter(r=>r.member_id===mine()),up=state.meetings.filter(m=>m.status==='confirmed'&&m.start_at.slice(0,10)>=dateNow()),due=deadlines(),unassigned=state.tasks.tasks.filter(t=>t.status==='unassigned');const noSchedule=activeMembers().filter(m=>!state.schedules.schedules.some(s=>s.member_id===m.id&&s.kind==='weekly'));
return `<div class="onboard"><b>처음 시작하나요?</b> 내 시간표를 입력하고, 팀 시간표에서 회의 시간을 확인한 뒤, 과제와 역할을 살펴보세요. 빈 시간은 기간을 확인하기 전까지 미입력으로 표시됩니다.</div><div class="grid"><section class="card"><h2>전체 진행률</h2>${progressBar(state.tasks.progress)}<p class="muted tiny">완료한 담당 역할을 기준으로 계산합니다. 시간 추정치가 아닙니다.</p></section><section class="card"><h2>내 진행 중 역할</h2><div class="stat">${roles.filter(r=>r.status==='doing').length}</div><span class="muted">전체 ${roles.length}개</span></section><section class="card"><h2>다가오는 회의</h2><div class="stat">${up.length}</div>${up.slice(0,2).map(m=>`<div class="tiny">${esc(m.title)} · ${esc(m.start_at.replace('T',' '))}</div>`).join('')}</section><section class="card"><h2>마감 임박</h2><div class="stat">${due.filter(t=>t.days>=0&&t.days<=3).length}</div><span class="muted tiny">3일 이내</span></section><section class="card"><h2>기한 초과</h2><div class="stat">${due.filter(t=>t.days<0).length}</div></section><section class="card"><h2>미배정 과제</h2><div class="stat">${unassigned.length}</div></section></div><section class="card" style="margin-top:16px"><h2>시간표 미입력 팀원</h2>${noSchedule.length?noSchedule.map(m=>`<span class="pill unknown">${esc(m.nickname)}</span> `).join(''):'모든 팀원이 반복 일정을 등록했습니다.'}</section><section class="card" style="margin-top:16px"><h2>내 알림</h2>${state.notifications.length?state.notifications.slice(0,8).map(n=>`<div class="list-item row between"><div>${n.read_at?'':'● '}${esc(n.body)} <small class="muted">${fmt(n.created_at)}</small></div>${n.read_at?'':`<button class="small ghost" data-action="read-notice" data-id="${n.id}">읽음</button>`}</div>`).join(''):'새 알림이 없습니다.'}</section>`}
function scheduleForm(s={}){
 const kind=s.kind||'weekly',start=hm(s.start_min??540),end=hm((s.end_min??600)%1440);
 const selectedDays=s.days||[s.day??day(state.mobileDay)],isDate=kind==='date',fixedStatus=['sleep','avoid'].includes(kind);
 const status=kind==='sleep'?'unavailable':kind==='avoid'?'avoid':s.status||'unavailable';
 return `<form id="schedule-form" data-id="${s.id||''}"><label>종류<select name="kind" id="schedule-kind"><option value="weekly" ${kind==='weekly'?'selected':''}>매주 반복</option><option value="date" ${isDate?'selected':''}>특정 날짜 예외</option><option value="sleep" ${kind==='sleep'?'selected':''}>취침시간</option><option value="avoid" ${kind==='avoid'?'selected':''}>반복 기피 시간</option></select></label>
 <fieldset class="schedule-days" data-schedule-days ${isDate?'hidden':''}><legend>반복 요일 · 여러 개 선택 가능</legend><div class="weekday-choices">${[1,2,3,4,5,6,0].map(i=>`<label class="weekday-choice"><input type="checkbox" name="days" value="${i}" ${selectedDays.includes(i)?'checked':''} ${isDate?'disabled':''}><span>${week[i]}</span></label>`).join('')}</div><div class="row"><button type="button" class="link small" data-action="schedule-days" data-mode="weekdays">평일</button><button type="button" class="link small" data-action="schedule-days" data-mode="all">매일</button><button type="button" class="link small" data-action="schedule-days" data-mode="none">선택 해제</button></div></fieldset>
 <label data-schedule-date ${isDate?'':'hidden'}>날짜<input type="date" name="date" value="${esc(s.date||state.mobileDay)}" ${isDate?'required':'disabled'}></label>
 <div class="form-row"><label>시작<input type="time" name="start" step="1800" value="${start}" required></label><label>종료<input type="time" name="end" step="1800" value="${end}" required></label><label>상태<select name="status" ${fixedStatus?'disabled':''}>${['available','unavailable','avoid'].map(x=>`<option value="${x}" ${status===x?'selected':''}>${label(x)}</option>`).join('')}</select></label></div>
 <label>일정 이름<input name="title" maxlength="100" value="${esc(s.title||'')}" placeholder="예: 수업"></label><label class="check"><input type="checkbox" name="share_title" ${s.share_title?'checked':''}>팀원에게 일정 이름 공유</label>
 <p class="muted tiny">종료가 시작보다 빠르거나 같으면 다음 날까지 이어집니다. 가능은 초록색, 불가능·취침은 빨간색, 기피는 노란색으로 표시합니다.${s.id?' 여러 요일을 선택하면 현재 일정을 수정하고 추가 요일에 같은 일정을 등록합니다.':''}</p>
 <div class="row"><button ${state.scheduleSelectionMode?'disabled':''}>저장</button><button type="button" class="ghost" data-action="toggle-schedule-selection" aria-pressed="${state.scheduleSelectionMode}" ${state.scheduleDeleting?'disabled':''}>${state.scheduleSelectionMode?'선택 취소':'선택'}</button>${s.id?`<button type="button" class="danger" data-action="delete-schedule" data-id="${s.id}" data-version="${s.version}">삭제</button>`:''}</div></form>`
}
function syncScheduleForm(form){
 const kind=form.elements.kind.value,isDate=kind==='date',fixed=['sleep','avoid'].includes(kind);
 form.querySelector('[data-schedule-days]').hidden=isDate;
 form.querySelectorAll('input[name=days]').forEach(input=>input.disabled=isDate);
 form.querySelector('[data-schedule-date]').hidden=!isDate;
 form.elements.date.disabled=!isDate;form.elements.date.required=isDate;
 form.elements.status.disabled=fixed;
 if(fixed)form.elements.status.value=kind==='sleep'?'unavailable':'avoid';
}
function scheduleStatus(memberId,date,from){const data=state.schedules,prev=addDays(date,-1),except=d=>data.exceptions.some(x=>x.member_id===memberId&&x.date===d),segments=[];for(const s of data.schedules.filter(s=>s.member_id===memberId)){const allowed=d=>['sleep','avoid'].includes(s.kind)||s.kind===(except(d)?'date':'weekly');if(allowed(date)&&(s.kind==='date'?s.date===date:s.day===day(date)))segments.push({s,a:s.start_min,b:s.end_min});if(s.end_min>1440&&allowed(prev)&&(s.kind==='date'?s.date===prev:s.day===day(prev)))segments.push({s,a:s.start_min-1440,b:s.end_min-1440})}const active=segments.filter(x=>x.a<from+30&&x.b>from),start=`${date}T${hm(from)}:00`,end=`${from+30===1440?addDays(date,1):date}T${hm(from+30)}:00`;if(data.meetings.some(m=>m.status==='confirmed'&&m.attendees.includes(memberId)&&m.start_at<end&&m.end_at>start)||active.some(x=>x.s.kind==='sleep'||x.s.status==='unavailable'))return 'unavailable';const cover=xs=>{let edge=from;for(const x of xs.sort((a,b)=>a.a-b.a)){if(x.a>edge)break;edge=Math.max(edge,x.b);if(edge>=from+30)return true}return false};const confirmed=data.confirmations.some(c=>c.member_id===memberId&&c.start_date<=date&&c.end_date>=date),available=active.filter(x=>x.s.status==='available'),avoid=active.filter(x=>x.s.kind==='avoid'||x.s.status==='avoid');if(avoid.length)return confirmed||cover([...available,...avoid])?'avoid':'unknown';if(confirmed||cover(available))return 'available';return 'unknown'}
function scheduleSelectionControls(){
 if(!state.scheduleSelectionMode)return '';
 const count=Object.keys(state.selectedSchedules).length,busy=state.scheduleDeleting;
 return `<div class="schedule-selection-panel"><p><b>일정 선택 · ${count}개 선택됨</b><br><span class="tiny">일정 막대 또는 목록의 체크박스로 선택하세요. 반복 일정은 해당 요일의 모든 주에서 삭제되고, 자정을 넘는 막대는 하나의 일정으로 선택됩니다. 확정 회의는 선택 대상에서 제외됩니다.</span></p><div class="row"><button type="button" class="small ghost" data-action="select-all-schedules" ${busy?'disabled':''}>등록한 일정 전체 선택</button><button type="button" class="small ghost" data-action="clear-schedule-selection" ${busy?'disabled':''}>선택 해제</button><button type="button" class="small danger" data-action="delete-selected-schedules" ${!count||busy?'disabled':''}>${busy?'삭제 중…':`선택 삭제 (${count})`}</button><button type="button" class="small ghost" data-action="toggle-schedule-selection" ${busy?'disabled':''}>취소</button></div></div>`;
}
function scheduleList(my){
 return my.length?my.map(s=>`<div class="list-item row between ${state.selectedSchedules[s.id]!==undefined?'schedule-list-selected':''}"><div>${state.scheduleSelectionMode?`<label class="check"><input type="checkbox" class="schedule-select-checkbox" data-id="${s.id}" ${state.selectedSchedules[s.id]!==undefined?'checked':''} ${state.scheduleDeleting?'disabled':''}><span>${esc(s.title||({'sleep':'취침','avoid':'기피'}[s.kind]||'이름 없음'))}</span></label>`:`<b>${esc(s.title||({'sleep':'취침','avoid':'기피'}[s.kind]||'이름 없음'))}</b>`} <span class="pill ${s.status}">${label(s.status)}</span><div class="muted tiny">${s.kind==='date'?s.date:week[s.day]+'요일'} · ${calendarTime(s.start_min)}~${s.end_min===1440?'24:00':hm(s.end_min%1440)}${s.end_min>1440?' (다음 날)':''}</div></div>${state.scheduleSelectionMode?'':`<button class="small ghost" data-action="edit-schedule" data-id="${s.id}">수정</button>`}</div>`).join(''):'등록된 일정이 없습니다.';
}
function toggleScheduleSelection(id,checked){
 if(!state.scheduleSelectionMode||state.scheduleDeleting)return;
 const schedule=state.schedules.schedules.find(s=>s.id===id&&s.member_id===mine());if(!schedule)return;
 const select=checked??state.selectedSchedules[id]===undefined;
 if(select)state.selectedSchedules[id]=schedule.version;else delete state.selectedSchedules[id];
 state.scheduleDeleteRequest=null;render();
}
function mineView(){
 const my=state.schedules.schedules.filter(s=>s.member_id===mine()),date=state.mobileDay,start=addDays(date,-((day(date)+6)%7));
 const calendarOptions={data:state.schedules,memberId:mine(),getStatus:(date,minute)=>scheduleStatus(mine(),date,minute),selectionMode:state.scheduleSelectionMode,selectedScheduleIds:new Set(Object.keys(state.selectedSchedules)),selectionBusy:state.scheduleDeleting};
 return `<div class="schedule-layout"><section class="card schedule-sidebar"><h2>시간 입력</h2>${scheduleForm()}<hr><h3>등록한 일정</h3><div class="list">${scheduleList(my)}</div></section>
 <div class="stack schedule-main"><section class="card"><div class="row between"><h2>내 시간표</h2><button class="small" data-action="add-schedule" ${state.scheduleSelectionMode?'disabled':''}>일정 추가</button></div><p class="muted tiny">00:00~24:00 전체를 1시간 눈금으로 보여 줍니다. 일정 막대를 누르면 수정할 수 있고, 빈 시간은 클릭하거나 같은 날에서 드래그해 등록할 수 있습니다.</p>
 ${scheduleSelectionControls()}<div class="calendar-legend"><span><i class="available"></i>가능</span><span><i class="unavailable"></i>불가능·취침</span><span><i class="avoid"></i>기피</span><span><i class="unknown"></i>미입력</span></div>
 <div class="calendar-desktop"><div class="row between calendar-controls"><div class="row"><button class="small ghost" data-action="schedule-navigate" data-offset="-7">이전 주</button><button class="small ghost" data-action="schedule-today">오늘</button><button class="small ghost" data-action="schedule-navigate" data-offset="7">다음 주</button></div><label>기준 날짜<input id="personal-week" type="date" value="${date}"></label></div>${renderCalendar({...calendarOptions,dates:Array.from({length:7},(_,i)=>addDays(start,i))})}</div>
 <div class="calendar-mobile"><div class="row between calendar-controls"><button class="small ghost" data-action="schedule-navigate" data-offset="-1" aria-label="이전 날">이전</button><label>날짜<input id="mobile-day" type="date" value="${date}"></label><button class="small ghost" data-action="schedule-navigate" data-offset="1" aria-label="다음 날">다음</button></div>${renderCalendar({...calendarOptions,dates:[date],single:true})}</div><p class="muted tiny">빈 시간은 기간을 확인한 경우에만 초록색으로 표시합니다. 일정이 없고 확인하지 않은 시간은 미입력입니다.</p></section>
 <section class="card"><h2>빈 시간 확인</h2><p class="muted tiny">반복 일정을 등록한 뒤 선택한 기간에만 나머지 빈 시간을 가능으로 확인합니다. 그 외 기간은 미입력입니다.</p><form id="confirm-form" class="form-row"><label>시작일<input type="date" name="start_date" value="${dateNow()}" required></label><label>종료일<input type="date" name="end_date" value="${addDays(dateNow(),6)}" required></label><button>이 기간 확인</button></form><h3 style="margin-top:18px">이전 주 복사</h3><p class="muted tiny">이전 주의 날짜 예외 일정을 선택한 주에 복사합니다. 대상 주의 기존 날짜 예외 일정은 대체됩니다.</p><form id="copy-week-form" class="row"><label>대상 주의 월요일<input type="date" name="targetStart" value="${addDays(dateNow(),(8-day(dateNow()))%7)}" required></label><button class="ghost">복사</button></form><h3 style="margin-top:18px">날짜 예외</h3><form id="exception-form" class="row"><input type="date" name="date" value="${date}" required><button class="ghost">빈 날짜 예외 적용</button></form>${state.schedules.exceptions.filter(e=>e.member_id===mine()).map(e=>`<div class="row between list-item">${e.date}<button class="small danger" data-action="delete-exception" data-date="${e.date}">예외 삭제</button></div>`).join('')}<p class="muted tiny">예외 날짜에는 반복 일정이 적용되지 않습니다. 필요하면 그 날짜의 일정을 별도로 추가하세요.</p></section></div></div>`
}
function selectedChecks(){return `<div class="row"><button class="small ghost" data-action="select-all">전체 선택</button><button class="small ghost" data-action="select-none">전체 해제</button></div><div class="member-checks">${activeMembers().map(m=>`<label><input type="checkbox" class="member-select" value="${m.id}" ${state.selected.includes(m.id)?'checked':''}>${esc(m.nickname)}</label>`).join('')}</div>`}
function teamView(){const start=addDays(state.heatDate,-day(state.heatDate)),selected=state.selected;const prefs=state.prefs||{};return `<section class="card"><h2>팀원 선택</h2>${selectedChecks()}<p class="muted tiny">선택한 팀원만 히트맵과 회의 추천에 포함됩니다. 추천 대상: <b>${selected.length?selected.map(member).map(esc).join(', '):'선택 없음'}</b></p></section><section class="card" style="margin-top:16px"><div class="row between"><h2>주간 시간표</h2><label>기준 날짜<input id="heat-date" type="date" value="${state.heatDate}"></label></div><div class="row tiny muted">가능 인원이 많을수록 진해집니다. <span class="legend"></span></div><div class="scroll"><div class="heat-grid"><div class="head">시간</div>${Array.from({length:7},(_,i)=>`<div class="head">${week[day(addDays(start,i))]} ${addDays(start,i).slice(5)}</div>`).join('')}${Array.from({length:26},(_,i)=>{const n=540+i*30;return `<div>${hm(n)}</div>${Array.from({length:7},(_,j)=>{const d=addDays(start,j),states=selected.map(id=>scheduleStatus(id,d,n)),ok=states.filter(x=>x==='available').length,unknown=states.filter(x=>x==='unknown').length;return `<div class="heat" style="--intensity:${selected.length?(0.08+ok/selected.length*.7).toFixed(2):0}" data-action="heat-cell" data-date="${d}" data-min="${n}">가능 ${ok} / 선택 ${selected.length}<br>미입력 ${unknown}</div>`}).join('')}`}).join('')}</div></div></section><section class="card" style="margin-top:16px"><h2>회의 시간 추천</h2>${selected.length?'':`<div class="alert">추천할 팀원을 한 명 이상 선택하세요.</div>`}<form id="recommend-form"><div class="form-row"><label>조회 시작<input type="date" name="startDate" value="${esc(prefs.startDate||dateNow())}" required></label><label>조회 종료<input type="date" name="endDate" value="${esc(prefs.endDate||addDays(dateNow(),6))}" required></label><label>회의 길이<select name="duration">${[30,60,90,120,150,180].map(n=>`<option value="${n}" ${Number(prefs.duration||60)===n?'selected':''}>${n}분</option>`).join('')}</select></label><label>추천 개수<input type="number" name="topN" min="1" max="20" value="${prefs.topN||5}"></label><label>검색 시작<input type="time" name="from" step="1800" value="${hm(prefs.from??540)}"></label><label>검색 종료<input type="time" name="to" step="1800" value="${hm(prefs.to??1320)}"></label><label>추천 방식<select name="mode"><option value="all" ${prefs.mode!=='max'?'selected':''}>전원 참석</option><option value="max" ${prefs.mode==='max'?'selected':''}>최대 인원 참석</option></select></label></div><h3>필수 참석자</h3><div class="member-checks">${selected.map(id=>`<label><input type="checkbox" class="required-select" value="${id}" ${state.required.includes(id)?'checked':''}>${esc(member(id))}</label>`).join('')}</div><div class="row"><label class="check"><input type="checkbox" name="weekends" ${prefs.weekends?'checked':''}>주말 포함</label><label class="check"><input type="checkbox" name="includeAvoid" ${prefs.includeAvoid?'checked':''}>기피 시간 포함</label><label class="check"><input type="checkbox" name="overlap" ${prefs.overlap?'checked':''}>겹치는 후보도 보기</label></div><button ${selected.length?'':'disabled'}>추천 찾기</button></form>${recommendResults()}</section><section class="card" style="margin-top:16px"><h2>확정된 회의</h2>${state.meetings.filter(m=>m.status==='confirmed').length?state.meetings.filter(m=>m.status==='confirmed').map(m=>`<div class="list-item row between"><div><b>${esc(m.title)}</b> · ${esc(m.start_at.replace('T',' ').slice(0,16))}~${esc(m.end_at.slice(11,16))}<div class="muted tiny">${m.attendees.map(member).map(esc).join(', ')}${m.agenda?' · '+esc(m.agenda):''}</div></div>${state.me.role==='owner'?`<div class="row"><button class="small ghost" data-action="edit-meeting" data-id="${m.id}">수정</button><button class="small danger" data-action="cancel-meeting" data-id="${m.id}" data-version="${m.version}">취소</button></div>`:''}</div>`).join(''):'확정된 회의가 없습니다.'}</section>`}
function recommendResults(){if(!state.recommend)return '';const rows=state.recommend.items;return `<div style="margin-top:20px"><h3>추천 결과</h3>${rows.length?rows.map((r,i)=>`<div class="result"><div class="row between"><b>${r.date} (${week[day(r.date)]}) ${r.start}~${r.end}</b><span class="pill available">${r.attending.length} / ${r.total}명 가능</span></div><p class="tiny">참석 가능: ${r.attending.map(member).map(esc).join(', ')}<br>참석 불가: ${r.unavailable.length?r.unavailable.map(member).map(esc).join(', '):'없음'}<br>미확인: ${r.unknown.length?r.unknown.map(member).map(esc).join(', '):'없음'}<br>기피 시간 포함: ${r.avoidCount?'예 ('+r.avoidCount+'명)':'아니요'}</p><p class="muted tiny">${r.attending.length===r.total?'선택한 전원이 회의 전체 시간에 참석할 수 있습니다.':'회의 전체 시간에 참석 가능한 인원이 가장 많습니다.'}${r.avoidCount?' 기피 시간이 포함되어 후순위입니다.':''}</p>${state.me.role==='owner'?`<button class="small" data-action="confirm-meeting" data-index="${i}">회의 확정</button>`:''}</div>`).join(''):`<div class="alert">${state.prefs.mode==='all'?'선택한 전원이 참석 가능한 시간이 없습니다.':'조건에 맞는 시간이 없습니다.'} 회의 길이를 줄이거나 조회 기간을 늘리거나, 기피 시간 포함 또는 최대 인원 참석으로 바꿔 다시 검색해 보세요.${state.recommend.unknownMembers?.length?` 미입력 구간이 있는 팀원: ${state.recommend.unknownMembers.map(member).map(esc).join(', ')}.`:''} 미입력 시간은 참석 가능으로 확정하지 않습니다.</div>`}</div>`}
function taskForm(t={},parentId=''){return `<form id="task-form" data-id="${t.id||''}" data-version="${t.version||''}" data-parent="${parentId}"><label>제목<input name="title" value="${esc(t.title||'')}" required maxlength="150"></label><label>설명<textarea name="description">${esc(t.description||'')}</textarea></label><div class="form-row"><label>우선순위<select name="priority">${['low','normal','high'].map(x=>`<option value="${x}" ${t.priority===x?'selected':''}>${priorityText[x]}</option>`).join('')}</select></label><label>시작 예정일<input type="date" name="start_date" value="${esc(t.start_date||'')}"></label><label>목표 완료일<input type="date" name="target_date" value="${esc(t.target_date||'')}"></label><label>최종 마감일<input type="date" name="due_date" value="${esc(t.due_date||'')}"></label><label>예상 소요 시간<input type="number" name="estimate" min="0" step="0.5" value="${esc(t.estimate??'')}"></label></div><label>참고 링크<input type="url" name="link" value="${esc(t.link||'')}"></label>${state.me.role==='owner'?`<label>대표 담당자 (상위 과제 조율)<select name="lead_id"><option value="">없음</option>${activeMembers().map(m=>`<option value="${m.id}" ${t.lead_id===m.id?'selected':''}>${esc(m.nickname)}</option>`).join('')}</select></label>`:''}<button>저장</button></form>`}
function taskTree(){const tasks=state.tasks.tasks,roles=state.tasks.roles;function renderTask(t,depth){const children=tasks.filter(x=>x.parent_id===t.id),rs=roles.filter(x=>x.task_id===t.id),collapsed=state.collapsed.has(t.id),pct=t.progress===null?'':`${Math.round(t.progress*100)}%`,due=t.due_date?deadlineText(t):'';return `<div class="task depth-${depth}"><div class="row between"><div><button class="link small" data-action="toggle-task" data-id="${t.id}">${children.length?(collapsed?'▶':'▼'):'•'}</button><span class="task-title">${esc(t.title)}</span> <span class="pill ${t.status||'todo'}">${children.length?'상위 과제':label(t.status)}</span> <span class="pill">${priorityText[t.priority]}</span> ${pct?`<span class="muted tiny">${pct} 완료</span>`:''}</div><div class="row"><button class="small ghost" data-action="add-child" data-id="${t.id}" ${depth>=2?'disabled':''}>하위 추가</button><button class="small ghost" data-action="edit-task" data-id="${t.id}">편집</button><button class="small ghost" data-action="move-task" data-id="${t.id}" data-dir="-1">↑</button><button class="small ghost" data-action="move-task" data-id="${t.id}" data-dir="1">↓</button><button class="small danger" data-action="delete-task" data-id="${t.id}" data-version="${t.version}">삭제</button></div></div>${t.description?`<p class="muted tiny">${esc(t.description)}</p>`:''}<div class="tiny muted">${t.target_date?'목표 '+t.target_date+' · ':''}${t.due_date?'최종 마감 '+t.due_date+' '+due:''}${t.lead_id?' · 대표 '+esc(member(t.lead_id)):''}${t.link?` · <a href="${esc(t.link)}" target="_blank" rel="noopener">참고 링크</a>`:''}</div>${!children.length?`<div class="list">${rs.length?rs.map(r=>`<div class="role row between"><div><b>${esc(member(r.member_id))}</b> · ${esc(r.description||'담당 역할')} <span class="pill ${r.status}">${label(r.status)}</span> <span class="muted tiny">${r.estimate??'시간 미입력'}${r.estimate==null?'':'시간'}</span></div><div class="row">${r.member_id===mine()||state.me.role==='owner'?`<select class="role-status" data-id="${r.id}" data-version="${r.version}">${['todo','doing','review','done','blocked'].map(x=>`<option value="${x}" ${r.status===x?'selected':''}>${label(x)}</option>`).join('')}</select>`:''}${state.me.role==='owner'?`<button class="small ghost" data-action="edit-role" data-id="${r.id}">편집</button>`:''}</div></div>`).join(''):'<span class="muted tiny">미배정</span>'}</div>${state.me.role==='owner'?`<button class="small ghost" data-action="add-role" data-id="${t.id}">담당 역할 추가</button>`:''}`:''}<div class="row"><button class="link small" data-action="comments" data-id="${t.id}">댓글</button><button class="link small" data-action="history" data-id="${t.id}">변경 이력</button></div>${collapsed?'':children.map(c=>renderTask(c,depth+1)).join('')}</div>`}return tasks.filter(t=>!t.parent_id).map(t=>renderTask(t,0)).join('')}
function deadlineText(t){const diff=Math.round((new Date(`${t.due_date}T12:00Z`)-new Date(`${dateNow()}T12:00Z`))/86400000);return t.status==='done'?'':diff<0?`<span class="pill late">${-diff}일 지연</span>`:diff===0?'<span class="pill review">오늘 마감</span>':`<span class="pill">${diff}일 남음</span>`}
function tasksView(){return `<div class="row between" style="margin-bottom:16px"><p class="muted">대과제 → 중간 과제 → 세부 과제. 담당 역할은 말단 과제에 배정합니다.</p><button data-action="add-task">새 과제</button></div>${state.tasks.tasks.length?taskTree():'<div class="card empty">아직 등록된 과제가 없습니다. 새 과제를 추가해 주세요.</div>'}`}
function roleForm(r={},taskId=''){return `<form id="role-form" data-id="${r.id||''}" data-task="${taskId||r.task_id||''}" data-version="${r.version||''}"><label>담당자<select name="member_id"><option value="">미배정</option>${activeMembers().map(m=>`<option value="${m.id}" ${r.member_id===m.id?'selected':''}>${esc(m.nickname)}</option>`).join('')}</select></label><label>구체적인 역할<input name="description" value="${esc(r.description||'')}" placeholder="예: 그래프 제작"></label><label>예상 소요 시간<input type="number" name="estimate" min="0" step="0.5" value="${esc(r.estimate??'')}"></label><button>저장</button>${r.id?`<button type="button" class="danger" data-action="delete-role" data-id="${r.id}" data-version="${r.version}">역할 삭제</button>`:''}</form>`}
function settingsView(){const p=state.project;return `<div class="cols"><div class="stack"><section class="card"><h2>프로젝트 정보</h2>${state.me.role==='owner'?`<form id="project-form"><label>이름<input name="name" value="${esc(p.name)}" required></label><label>설명<textarea name="description">${esc(p.description)}</textarea></label><label>목표 종료일<input type="date" name="goal_date" value="${esc(p.goal_date||'')}"></label><label class="check"><input type="checkbox" name="invite_open" ${p.invite_open?'checked':''}>신규 참여 허용</label><button>설정 저장</button></form>`:`<p>${esc(p.description||'설명 없음')}</p><p>목표 종료일: ${p.goal_date||'미설정'}</p>`}</section><section class="card"><h2>초대</h2><p class="muted tiny">초대 코드는 프로젝트 참여용입니다. 개인 복구 코드와 다릅니다.</p><span class="pill ${p.invite_open?'available':'unavailable'}">${p.invite_open?'참여 가능':'참여 중단'}</span>${state.me.role==='owner'?`<p>보안상 기존 초대 코드는 다시 표시하지 않습니다. 새 코드를 발급하면 이전 코드는 무효가 됩니다.</p><div class="row"><button data-action="rotate-invite">코드·링크 재발급</button><button class="danger" data-action="close-invite">신규 참여 중단</button></div>${state.invite?`<div class="recovery"><code>${esc(state.invite)}</code></div><div class="row"><button class="ghost" data-copy="${esc(state.invite)}">코드 복사</button><button class="ghost" data-copy="${esc(location.origin+'/#invite='+encodeURIComponent(state.invite))}">링크 복사</button></div>`:''}`:''}</section></div><div class="stack"><section class="card"><h2>멤버 관리</h2>${p.members.map(m=>`<div class="list-item row between"><div><b>${esc(m.nickname)}</b> <span class="pill">${m.role==='owner'?'방장':'조원'}</span> ${m.active?'':'<span class="pill unavailable">탈퇴/제외</span>'}</div>${state.me.role==='owner'&&m.active&&m.role!=='owner'?`<button class="small danger" data-action="remove-member" data-id="${m.id}">제외</button>`:m.id===mine()&&m.role!=='owner'?`<button class="small danger" data-action="leave">탈퇴</button>`:''}</div>`).join('')}</section><section class="card"><h2>최근 변경 이력</h2><div id="audit-list" class="list"><button class="ghost" data-action="load-audit">이력 불러오기</button></div></section></div></div>`}
function progressPage(){
 const f=state.filter,tasks=state.tasks.tasks,roles=state.tasks.roles,leaves=tasks.filter(t=>!tasks.some(x=>x.parent_id===t.id));
 const inGroup=t=>{let x=t;while(x){if(x.id===f.group)return true;x=tasks.find(y=>y.id===x.parent_id)}return false};
 const picked=f.members||[];
 const filtered=leaves.filter(t=>!f.search||t.title.toLowerCase().includes(f.search.toLowerCase())).filter(t=>!f.status||t.status===f.status).filter(t=>!f.priority||t.priority===f.priority).filter(t=>!f.group||inGroup(t)).filter(t=>!f.unassigned||t.status==='unassigned').filter(t=>!picked.length||roles.some(r=>r.task_id===t.id&&picked.includes(r.member_id))).filter(t=>{if(!f.deadline)return true;const x=deadlines().find(y=>y.id===t.id);return x&&(f.deadline==='late'?x.days<0:x.days>=0&&x.days<=3)});
 const groups=tasks.filter(t=>tasks.some(x=>x.parent_id===t.id));
 const workload=activeMembers().map(m=>{const own=roles.filter(r=>r.member_id===m.id),open=own.filter(r=>r.status!=='done');return {m,done:own.length-open.length,total:own.length,open:open.length,hours:open.reduce((v,r)=>v+(r.estimate||0),0),unknown:open.filter(r=>r.estimate==null).length}});
 return `<section class="card"><h2>과제 필터</h2><div class="form-row"><label>제목 검색<input id="filter-search" value="${esc(f.search||'')}"></label><label>상태<select id="filter-status"><option value="">전체</option>${['unassigned','todo','doing','review','done','blocked'].map(x=>`<option value="${x}" ${f.status===x?'selected':''}>${label(x)}</option>`).join('')}</select></label><label>우선순위<select id="filter-priority"><option value="">전체</option>${['low','normal','high'].map(x=>`<option value="${x}" ${f.priority===x?'selected':''}>${priorityText[x]}</option>`).join('')}</select></label><label>마감<select id="filter-deadline"><option value="">전체</option><option value="soon" ${f.deadline==='soon'?'selected':''}>3일 이내</option><option value="late" ${f.deadline==='late'?'selected':''}>기한 초과</option></select></label><label>상위 과제<select id="filter-group"><option value="">전체</option>${groups.map(t=>`<option value="${t.id}" ${f.group===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select></label></div><div class="row" style="margin-top:12px"><button class="small ghost" data-action="filter-mine">내 과제</button><button class="small ghost" data-action="filter-all">전체 보기</button><label class="check"><input id="filter-unassigned" type="checkbox" ${f.unassigned?'checked':''}>미배정만</label></div><h3 style="margin-top:14px">담당 팀원 (여러 명 선택 가능)</h3><div class="member-checks">${activeMembers().map(m=>`<label><input class="progress-member" type="checkbox" value="${m.id}" ${picked.includes(m.id)?'checked':''}>${esc(m.nickname)}</label>`).join('')}</div></section><div class="cols" style="margin-top:16px"><section class="card"><h2>사람별 작업량</h2><p class="muted tiny">완료 전 역할 수와 역할별 남은 예상 시간입니다. 자동으로 담당자를 변경하지 않습니다.</p><table class="table"><tr><th>팀원</th><th>역할</th><th>시간</th></tr>${workload.map(w=>`<tr><td>${esc(w.m.nickname)}<div class="muted tiny">완료 ${w.done}/${w.total}</div></td><td>${w.open}</td><td>${w.hours}시간${w.unknown?`<div class="muted tiny">시간 미입력 ${w.unknown}개</div>`:''}</td></tr>`).join('')}</table><h3 style="margin-top:22px">상위 과제</h3>${groups.map(t=>`<div class="list-item row between"><b>${esc(t.title)}</b><span>${t.progress==null?'등록된 과제 없음':Math.round(t.progress*100)+'% 완료'}</span></div>`).join('')||'<p class="muted">상위 과제가 없습니다.</p>'}</section><section class="card"><h2>과제 현황</h2>${progressBar(state.tasks.progress)}<p class="muted tiny">말단 과제의 완료 역할 비율을 평균합니다. 시간 기반 추정치가 아닙니다.</p><div class="list">${filtered.length?filtered.map(t=>`<div class="list-item"><div class="row between"><b>${esc(t.title)}</b><span class="pill ${t.status}">${label(t.status)}</span></div><div class="muted tiny">${Math.round((t.progress||0)*100)}% 완료 · ${priorityText[t.priority]}${t.due_date?' · '+t.due_date+' '+deadlineText(t):''}</div><div class="tiny">${roles.filter(r=>r.task_id===t.id).map(r=>`${esc(member(r.member_id))}: ${esc(r.description||'담당')} (${label(r.status)})`).join(' · ')||'담당자 재지정 필요 / 미배정'}</div></div>`).join(''):'조건에 맞는 과제가 없습니다.'}</div></section></div>`
}
function modalView(){const m=state.modal;if(!m)return '';let content='';if(m.type==='schedule')content=scheduleForm(m.data||{});if(m.type==='task')content=taskForm(m.data||{},m.parentId||'');if(m.type==='role')content=roleForm(m.data||{},m.taskId||'');if(m.type==='heat'){const states=state.selected.map(id=>({id,status:scheduleStatus(id,m.date,m.min)}));content=`<p><b>${m.date} ${hm(m.min)}~${hm(m.min+30)}</b></p>${['available','unavailable','avoid','unknown'].map(x=>`<p><span class="pill ${x}">${label(x)}</span> ${states.filter(a=>a.status===x).map(a=>esc(member(a.id))).join(', ')||'없음'}</p>`).join('')}`;}if(m.type==='meeting'){const r=state.recommend.items[m.index];content=`<p><b>${r.date} ${r.start}~${r.end}</b></p><p>실제 참석 대상자를 확인하세요. 저장 직전 최신 일정과 회의 충돌을 다시 확인합니다.</p><form id="meeting-form" data-index="${m.index}"><label>회의 제목<input name="title" required placeholder="예: 주간 회의"></label><label>간단한 안건<textarea name="agenda"></textarea><div class="member-checks">${r.attending.map(id=>`<label><input type="checkbox" name="attendee" value="${id}" checked>${esc(member(id))}</label>`).join('')}</div><button>회의 확정</button></form>`}if(m.type==='meeting-edit'){const d=m.data,date=d.start_at.slice(0,10),end=d.end_at.slice(0,10)>date?'00:00':d.end_at.slice(11,16);content=`<form id="meeting-edit-form" data-id="${d.id}" data-version="${d.version}"><label>제목<input name="title" value="${esc(d.title)}" required></label><label>안건<textarea name="agenda">${esc(d.agenda)}</textarea></label><div class="form-row"><label>날짜<input type="date" name="date" value="${date}" required></label><label>시작<input type="time" name="start" step="1800" value="${d.start_at.slice(11,16)}" required></label><label>종료<input type="time" name="end" step="1800" value="${end}" required></label></div><h3>참석 대상</h3><div class="member-checks">${activeMembers().map(x=>`<label><input type="checkbox" name="attendee" value="${x.id}" ${d.attendees.includes(x.id)?'checked':''}>${esc(x.nickname)}</label>`).join('')}</div><p class="muted tiny">시간·참석자 변경은 저장 직전에 최신 일정과 충돌을 다시 확인합니다.</p><button>저장</button></form>`}if(m.type==='comments'){content=`<div id="comments-list">불러오는 중…</div><form id="comment-form" data-id="${m.taskId}"><label>댓글<textarea name="body" required></textarea></label><button>등록</button></form>`}if(m.type==='history'){content='<div id="history-list">불러오는 중…</div>'}return `<div class="modal-wrap"><div class="modal" role="dialog" aria-modal="true"><header><h2>${esc(m.title||'상세')}</h2><button data-action="close-modal" aria-label="닫기">×</button></header>${content}</div></div>`}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function openModal(modal){state.modal=modal;render();if(modal.type==='comments')loadComments(modal.taskId);if(modal.type==='history')loadHistory(modal.taskId)}
async function refresh(){await load()}
async function loadComments(taskId){try{const rows=await api(`/projects/${pid()}/comments/${taskId}`);const el=$('#comments-list');if(el)el.innerHTML=rows.length?rows.map(x=>`<div class="list-item"><b>${esc(x.nickname)}</b> <span class="muted tiny">${fmt(x.created_at)}</span><p>${esc(x.body)}</p></div>`).join(''):'댓글이 없습니다.'}catch(e){toast(e.message)}}
async function loadHistory(taskId){try{const rows=await api(`/projects/${pid()}/audit`),el=$('#history-list');if(el)el.innerHTML=rows.filter(x=>x.entity_id===taskId).map(x=>`<div class="list-item">${esc(x.nickname||'탈퇴한 팀원')} · ${esc(x.action)} · ${fmt(x.created_at)}</div>`).join('')||'이력이 없습니다.'}catch(e){toast(e.message)}}
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id)return;e.preventDefault();const data=formData(form),button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{
 if(form.id==='create-form'){form.dataset.requestId ||= crypto.randomUUID();const x=await action(()=>api('/projects','POST',{...data,requestId:form.dataset.requestId}));state.createResult=x;state.me=null;render();return}
 if(form.id==='join-form'){const x=await action(()=>api('/join','POST',data));state.createResult=x;state.me=null;location.hash='';render();return}
 if(form.id==='recover-form'){const x=await action(()=>api('/recover','POST',data));state.createResult=x;state.me=null;render();return}
 if(form.id==='schedule-form'){
  if(state.scheduleSelectionMode||state.scheduleDeleting)throw Error('선택 모드를 종료한 뒤 일정을 저장하세요.');
  let from=min(data.start),to=min(data.end);if(to<=from)to+=1440;
  const days=[...form.querySelectorAll('input[name=days]:checked')].map(x=>Number(x.value));
  if(data.kind!=='date'&&!days.length)throw Error('반복할 요일을 한 개 이상 선택하세요.');
  const status=data.kind==='sleep'?'unavailable':data.kind==='avoid'?'avoid':data.status;
  form.dataset.requestId ||= crypto.randomUUID();
  const body={kind:data.kind,days,date:data.kind==='date'?data.date:null,start_min:from,end_min:to,status,title:data.title,color:SCHEDULE_COLORS[status],share_title:!!data.share_title,requestId:form.dataset.requestId};
  if(form.dataset.id){const old=state.schedules.schedules.find(x=>x.id===form.dataset.id);await action(()=>api(`/projects/${pid()}/schedules/${old.id}`,'PATCH',{...body,version:old.version}))}
  else await action(()=>api(`/projects/${pid()}/schedules`,'POST',body));
  state.modal=null;await refresh();return
 }
 if(form.id==='confirm-form'){await action(()=>api(`/projects/${pid()}/confirmations`,'POST',data));await refresh();return}
 if(form.id==='copy-week-form'){if(day(data.targetStart)!==1)throw Error('대상 주의 월요일을 선택하세요.');if(!confirm('대상 주의 기존 날짜 예외 일정을 대체하고 이전 주를 복사할까요?'))return;const result=await action(()=>api(`/projects/${pid()}/schedules/copy-week`,'POST',data));toast(`${result.count}개 일정을 복사했습니다.`);await refresh();return}
 if(form.id==='exception-form'){await action(()=>api(`/projects/${pid()}/exceptions`,'POST',data));await refresh();return}
 if(form.id==='recommend-form'){const body={...data,selected:state.selected,required:state.required,duration:Number(data.duration),topN:Number(data.topN),from:min(data.from),to:min(data.to),weekends:!!data.weekends,includeAvoid:!!data.includeAvoid,overlap:!!data.overlap};state.recommend=await action(()=>api(`/projects/${pid()}/recommend`,'POST',body));state.prefs=body;render();return}
 if(form.id==='task-form'){form.dataset.requestId ||= crypto.randomUUID();const body={...data,parent_id:form.dataset.parent||null,estimate:data.estimate===''?null:Number(data.estimate),requestId:form.dataset.requestId,...(data.lead_id!==undefined?{lead_id:data.lead_id||null}:{})};let result;if(form.dataset.id){result=await action(()=>api(`/projects/${pid()}/tasks/${form.dataset.id}`,'PATCH',{...body,version:Number(form.dataset.version)}))}else{try{result=await action(()=>api(`/projects/${pid()}/tasks`,'POST',body))}catch(err){if(err.data?.needsRoleMove&&confirm('상위 과제에 있는 기존 담당 역할을 새 하위 과제로 이동할까요?'))result=await action(()=>api(`/projects/${pid()}/tasks`,'POST',{...body,move_roles:true}));else throw err}}state.modal=null;await refresh();if(result?.warning)toast(result.warning);return}
 if(form.id==='role-form'){const body={...data,estimate:data.estimate===''?null:Number(data.estimate),member_id:data.member_id||null};if(form.dataset.id)await action(()=>api(`/projects/${pid()}/roles/${form.dataset.id}`,'PATCH',{...body,version:Number(form.dataset.version)}));else await action(()=>api(`/projects/${pid()}/roles`,'POST',{...body,task_id:form.dataset.task}));state.modal=null;await refresh();return}
 if(form.id==='meeting-form'){form.dataset.requestId ||= crypto.randomUUID();const r=state.recommend.items[Number(form.dataset.index)];const attendees=[...form.querySelectorAll('input[name=attendee]:checked')].map(x=>x.value);const body={...state.prefs,selected:state.selected,required:state.required,date:r.date,start:r.start,end:r.end,attendees,title:data.title,agenda:data.agenda,requestId:form.dataset.requestId};await action(()=>api(`/projects/${pid()}/meetings`,'POST',body));state.modal=null;state.recommend=null;await refresh();return}
 if(form.id==='meeting-edit-form'){const attendees=[...form.querySelectorAll('input[name=attendee]:checked')].map(x=>x.value);if(!attendees.length)throw Error('참석 대상자를 한 명 이상 선택하세요.');if(data.end==='00:00'&&min(data.start)>0)data.end='24:00';if(min(data.end)<=min(data.start))throw Error('종료 시각은 시작 시각 이후여야 합니다.');await action(()=>api(`/projects/${pid()}/meetings/${form.dataset.id}`,'PATCH',{...data,attendees,version:Number(form.dataset.version)}));state.modal=null;await refresh();return}
 if(form.id==='comment-form'){await action(()=>api(`/projects/${pid()}/comments`,'POST',{task_id:form.dataset.id,body:data.body}));form.reset();await loadComments(form.dataset.id);return}
 if(form.id==='project-form'){await action(()=>api(`/projects/${pid()}`,'PATCH',{...data,goal_date:data.goal_date||null,invite_open:!!data.invite_open,version:state.project.version}));await refresh();return}
 }catch(err){if(form.id==='join-form'&&err.status===404){form.querySelector('.invite-error')?.remove();form.insertAdjacentHTML('afterbegin',`<div class="alert error invite-error">초대 코드가 잘못되었거나 참여가 중단되었습니다. 방장에게 새 코드를 요청하세요.</div>`)}if(!err.reported){save('저장 실패 · 다시 시도하세요',true);toast(err.message)}}finally{if(button)button.disabled=false}});
document.addEventListener('change',async e=>{const x=e.target;if(x.classList.contains('schedule-select-checkbox')){toggleScheduleSelection(x.dataset.id,x.checked);return}if(x.id==='schedule-kind'){syncScheduleForm(x.closest('form'));return}if(x.classList.contains('member-select')){state.selected=[...document.querySelectorAll('.member-select:checked')].map(x=>x.value);state.required=state.required.filter(id=>state.selected.includes(id));state.recommend=null;render()}else if(x.classList.contains('required-select'))state.required=[...document.querySelectorAll('.required-select:checked')].map(x=>x.value);else if(x.classList.contains('progress-member')){state.filter.members=[...document.querySelectorAll('.progress-member:checked')].map(x=>x.value);render()}else if(x.id==='heat-date'){state.heatDate=x.value;render()}else if(x.id==='mobile-day'||x.id==='personal-week'){if(x.value){state.mobileDay=x.value;render()}}else if(x.classList.contains('role-status')){try{await action(()=>api(`/projects/${pid()}/roles/${x.dataset.id}`,'PATCH',{version:Number(x.dataset.version),status:x.value}));await refresh()}catch{await refresh()}}else if(x.id.startsWith('filter-')){state.filter[x.id.slice(7)]=x.type==='checkbox'?x.checked:x.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='filter-search'){state.filter.search=e.target.value;const pos=e.target.selectionStart;render();const input=$('#filter-search');input.focus();input.setSelectionRange(pos,pos)}});
let dragStart=null,suppressSlotClickUntil=0;
document.addEventListener('pointerdown',e=>{const slot=e.target.closest('.calendar-hour');if(slot&&!state.scheduleSelectionMode&&e.pointerType==='mouse'&&e.button===0)dragStart={date:slot.dataset.date,min:Number(slot.dataset.min)}});
document.addEventListener('pointercancel',()=>{dragStart=null});
document.addEventListener('pointerup',e=>{if(!dragStart)return;const start=dragStart;dragStart=null;const slot=document.elementFromPoint(e.clientX,e.clientY)?.closest('.calendar-hour');if(slot&&slot.dataset.date===start.date&&Number(slot.dataset.min)!==start.min){const a=Math.min(start.min,Number(slot.dataset.min)),b=Math.max(start.min,Number(slot.dataset.min))+60;suppressSlotClickUntil=Date.now()+500;openModal({type:'schedule',title:'시간 등록',data:{kind:'date',date:start.date,start_min:a,end_min:b,status:'unavailable'}})}});
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;state.modal=null;render();return}const copy=e.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy);toast('복사했습니다.')}catch{toast('복사할 수 없습니다. 텍스트를 직접 선택해 주세요.')}return}const x=e.target.closest('[data-action]');if(!x)return;const a=x.dataset.action;try{
 if(a==='enter'){state.createResult=null;await load();return}
 if(a==='logout'){await api('/logout','POST',{});state={...state,me:null,project:null,createResult:null,selectionInitialized:false,selected:[],required:[],scheduleSelectionMode:false,selectedSchedules:{},scheduleDeleteRequest:null};render();return}
 if(a==='close-modal'){state.modal=null;render();return}
 if(a==='select-all'){state.selected=activeMembers().map(x=>x.id);state.recommend=null;render();return}
 if(a==='select-none'){state.selected=[];state.required=[];state.recommend=null;render();return}
 if(a==='filter-mine'){state.filter.members=[mine()];state.filter.unassigned=false;render();return}
 if(a==='filter-all'){state.filter={};render();return}
 if(a==='pick-slot'){if(state.scheduleSelectionMode||Date.now()<suppressSlotClickUntil)return;const n=Number(x.dataset.min);openModal({type:'schedule',title:'시간 등록',data:{kind:'date',date:x.dataset.date,start_min:n,end_min:n+Number(x.dataset.step||60),status:'unavailable'}});return}
 if(a==='add-schedule'){if(state.scheduleSelectionMode||state.scheduleDeleting)return;openModal({type:'schedule',title:'일정 등록'});return}
 if(a==='schedule-navigate'){state.mobileDay=addDays(state.mobileDay,Number(x.dataset.offset));render();return}
 if(a==='schedule-today'){state.mobileDay=dateNow();render();return}
 if(a==='schedule-days'){for(const input of x.closest('form').querySelectorAll('input[name=days]'))input.checked=x.dataset.mode==='all'||(x.dataset.mode==='weekdays'&&Number(input.value)>0&&Number(input.value)<6);return}
 if(a==='calendar-meeting'){state.tab='team';render();return}
 if(a==='heat-cell'){openModal({type:'heat',title:'시간별 팀원 상태',date:x.dataset.date,min:Number(x.dataset.min)});return}
 if(a==='toggle-schedule-selection'){
  if(state.scheduleDeleting)return;
  state.scheduleSelectionMode=!state.scheduleSelectionMode;state.selectedSchedules={};state.scheduleDeleteRequest=null;state.modal=null;state.tab='mine';render();return;
 }
 if(a==='select-schedule'){toggleScheduleSelection(x.dataset.id);return}
 if(a==='select-all-schedules'){
  if(!state.scheduleSelectionMode||state.scheduleDeleting)return;
  state.selectedSchedules=Object.fromEntries(state.schedules.schedules.filter(s=>s.member_id===mine()).map(s=>[s.id,s.version]));state.scheduleDeleteRequest=null;render();return;
 }
 if(a==='clear-schedule-selection'){if(state.scheduleDeleting)return;state.selectedSchedules={};state.scheduleDeleteRequest=null;render();return}
 if(a==='delete-selected-schedules'){
  if(!state.scheduleSelectionMode||state.scheduleDeleting)return;
  const items=Object.entries(state.selectedSchedules).map(([id,version])=>({id,version}));if(!items.length)return;
  const schedules=items.map(item=>state.schedules.schedules.find(s=>s.id===item.id)).filter(Boolean);
  const details=schedules.map(s=>`• ${s.title||({'sleep':'취침','avoid':'기피'}[s.kind]||'이름 없음')} · ${s.kind==='date'?s.date:week[s.day]+'요일 매주 반복'} · ${hm(s.start_min)}~${s.end_min===1440?'24:00':hm(s.end_min%1440)}${s.end_min>1440?' (다음 날)':''}`).join('\n');
  if(!confirm(`선택한 일정 ${items.length}개를 삭제할까요?\n\n${details}\n\n반복 일정은 해당 요일의 모든 주에서 삭제됩니다. 날짜 예외와 빈 시간 확인 범위는 유지됩니다.`))return;
  state.scheduleDeleteRequest ||= {items,requestId:crypto.randomUUID()};state.scheduleDeleting=true;render();
  try{
   const result=await action(()=>api(`/projects/${pid()}/schedules/bulk-delete`,'POST',state.scheduleDeleteRequest));
   state.schedules.schedules=state.schedules.schedules.filter(s=>!state.selectedSchedules[s.id]);state.selectedSchedules={};state.scheduleDeleteRequest=null;state.scheduleSelectionMode=false;
   toast(`${result.deleted}개 일정을 삭제했습니다.`);
   try{await refresh()}catch{save('삭제 완료 · 목록 갱신에 실패했습니다. 새로고침하세요.',true)}
  }catch(err){
   if(err.status===409){state.selectedSchedules={};state.scheduleDeleteRequest=null;try{await refresh()}catch{}}
  }finally{state.scheduleDeleting=false;render()}
  return;
 }
 if(a==='edit-schedule'){if(state.scheduleSelectionMode){toggleScheduleSelection(x.dataset.id);return}openModal({type:'schedule',title:'일정 수정',data:state.schedules.schedules.find(s=>s.id===x.dataset.id)});return}
 if(a==='delete-schedule'){if(!confirm('이 일정을 삭제할까요?'))return;await action(()=>api(`/projects/${pid()}/schedules/${x.dataset.id}`,'DELETE',{version:Number(x.dataset.version)}));state.modal=null;await refresh();return}
 if(a==='delete-exception'){if(!confirm('날짜 예외와 해당 날짜 일정을 삭제할까요?'))return;await action(()=>api(`/projects/${pid()}/exceptions/${x.dataset.date}`,'DELETE',{}));await refresh();return}
 if(a==='confirm-meeting'){openModal({type:'meeting',title:'회의 확정',index:Number(x.dataset.index)});return}
 if(a==='edit-meeting'){openModal({type:'meeting-edit',title:'회의 수정',data:state.meetings.find(m=>m.id===x.dataset.id)});return}
 if(a==='cancel-meeting'){if(!confirm('이 회의를 취소할까요? 참석자의 시간표에 추가된 회의 점유도 제거됩니다.'))return;await action(()=>api(`/projects/${pid()}/meetings/${x.dataset.id}`,'PATCH',{version:Number(x.dataset.version),cancel:true}));await refresh();return}
 if(a==='add-task'){openModal({type:'task',title:'새 과제'});return}
 if(a==='add-child'){openModal({type:'task',title:'하위 과제 추가',parentId:x.dataset.id});return}
 if(a==='edit-task'){openModal({type:'task',title:'과제 편집',data:state.tasks.tasks.find(t=>t.id===x.dataset.id)});return}
 if(a==='toggle-task'){state.collapsed.has(x.dataset.id)?state.collapsed.delete(x.dataset.id):state.collapsed.add(x.dataset.id);render();return}
 if(a==='move-task'){const t=state.tasks.tasks.find(t=>t.id===x.dataset.id),peers=state.tasks.tasks.filter(y=>y.parent_id===t.parent_id),index=peers.findIndex(y=>y.id===t.id)+Number(x.dataset.dir);if(index<0||index>=peers.length)return;await action(()=>api(`/projects/${pid()}/tasks/reorder`,'POST',{id:t.id,position:index}));await refresh();return}
 if(a==='delete-task'){const t=state.tasks.tasks.find(t=>t.id===x.dataset.id),desc=state.tasks.tasks.filter(y=>y.parent_id===t.id).length;if(!confirm(`과제 “${t.title}”을 삭제할까요? ${desc?'하위 과제와 역할도 함께 삭제됩니다.':''}`))return;try{await action(()=>api(`/projects/${pid()}/tasks/${t.id}`,'DELETE',{version:t.version,confirm_descendants:true}));await refresh()}catch{}return}
 if(a==='add-role'){openModal({type:'role',title:'담당 역할 추가',taskId:x.dataset.id});return}
 if(a==='edit-role'){openModal({type:'role',title:'담당 역할 편집',data:state.tasks.roles.find(r=>r.id===x.dataset.id)});return}
 if(a==='delete-role'){if(!confirm('담당 역할을 삭제할까요?'))return;await action(()=>api(`/projects/${pid()}/roles/${x.dataset.id}`,'DELETE',{version:Number(x.dataset.version)}));state.modal=null;await refresh();return}
 if(a==='comments'){openModal({type:'comments',title:'과제 댓글',taskId:x.dataset.id});return}
 if(a==='history'){openModal({type:'history',title:'변경 이력',taskId:x.dataset.id});return}
 if(a==='read-notice'){await action(()=>api(`/projects/${pid()}/notifications/${x.dataset.id}/read`,'POST',{}));await refresh();return}
 if(a==='rotate-invite'){if(!confirm('새 초대 코드를 발급하면 이전 코드는 사용할 수 없습니다. 계속할까요?'))return;const r=await action(()=>api(`/projects/${pid()}/invite/rotate`,'POST',{}));state.invite=r.inviteCode;await refresh();return}
 if(a==='close-invite'){if(!confirm('신규 참여를 중단할까요?'))return;await action(()=>api(`/projects/${pid()}/invite/close`,'POST',{}));await refresh();return}
 if(a==='remove-member'||a==='leave'){if(!confirm(a==='leave'?'프로젝트에서 탈퇴할까요? 과제 기록은 유지됩니다.':'팀원을 제외할까요? 담당 역할은 재지정할 때까지 기록으로 남습니다.'))return;await action(()=>api(`/projects/${pid()}/members/${a==='leave'?mine():x.dataset.id}`,'DELETE',{}));if(a==='leave'){state.me=null;render()}else await refresh();return}
 if(a==='load-audit'){const rows=await api(`/projects/${pid()}/audit`),el=$('#audit-list');if(el)el.innerHTML=rows.length?rows.map(r=>`<div class="list-item tiny">${esc(r.nickname||'탈퇴한 팀원')} · ${esc(r.entity)} ${esc(r.action)} · ${fmt(r.created_at)}</div>`).join(''):'이력이 없습니다.';return}
 }catch(err){toast(err.message)}});
load().catch(e=>{$('#app').innerHTML=`<div class="auth"><div class="card error"><h2>${e.status===403?'접근 권한이 없습니다':'불러오지 못했습니다'}</h2><p>${esc(e.message)}</p><button onclick="location.reload()">다시 시도</button></div></div>`});
setInterval(()=>{if(state.me&&!state.modal&&!state.scheduleDeleting&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))load().catch(()=>save('자동 갱신 실패 · 다시 시도하세요',true))},15000);
